function RestaurantSection({ title, list, onSelectRestaurant }) {
  return (
    <section className="restaurants-section">
      <h1>{title}</h1>
      {list.length === 0 ? (
        <p className="dining-empty-state">No restaurants match your selected filters. Try changing or clearing your filters.</p>
      ) : (
        <div className="restaurant-grid">
          {list.map((restaurant) => {
            const features = DINING_RESTAURANT_FEATURES[restaurant.name] || {};
            return (
              <article
                className="restaurant-card restaurant-card-clickable"
                key={restaurant.name}
                role="button"
                tabIndex={0}
                onClick={() => onSelectRestaurant?.(restaurant)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    onSelectRestaurant?.(restaurant);
                  }
                }}
              >
                <div className="restaurant-image-wrapper">
                  <img src={restaurant.image} alt={restaurant.name} className="restaurant-image" loading="lazy" />
                  {features.offer && <span className="dining-offer-badge">{features.offer}</span>}
                  <button className="heart" type="button" aria-label={`Save ${restaurant.name}`} onClick={(event) => event.stopPropagation()}>♡</button>
                </div>
                <div className="restaurant-info">
                  <div className="restaurant-title">
                    <h3>{restaurant.displayName || restaurant.name}</h3>
                    <span className="rating">{restaurant.rating} ★</span>
                  </div>
                  <p className="cuisine">{restaurant.cuisine || restaurant.cusine || "Cuisine not listed"}</p>
                  <div className="restaurant-bottom"><span>{restaurant.price || "Price not listed"}</span><span>{restaurant.location}</span></div>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}




