        {(photoFilter === "All" || photoFilter === "Ambience") && <><h3 className="cassava-gallery-subheading">Ambience · 6 photos</h3><div className="cassava-photo-grid">{cassavaAmbiencePhotos.map((src,i)=><button type="button" key={`amb-${i}`} onClick={()=>setPhotoLightbox({src,kind:"Ambience",index:i})}><img src={src} alt={`Cassava restaurant ambience ${i+1}`} /></button>)}</div></>}
