          <label><span>♙</span><select value={guestCount} onChange={e => setGuestCount(e.target.value)}>{[1,2,3,4,5,6,7,8].map(n => <option key={n}>{n} {n === 1 ? "guest" : "guests"}</option>)}</select></label>
