// Shared search matcher for Dining Out and Delivery. It searches restaurant metadata
// plus any menu/dish/tag fields present in the restaurant data.
const SEARCH_SYNONYMS = {
  "fried rice": ["rice", "chinese", "asian"],
  "chicken mandhi": ["mandhi", "madhbi", "arabian", "middle eastern"],
  "mandhi": ["mandhi", "madhbi", "arabian"],
  "shawarma": ["shawarma", "arabian", "rolls", "middle eastern"],
  "biryani": ["biryani", "rice"],
  "pizza": ["pizza", "pizzeria", "italian"],
  "burger": ["burger", "burgers", "american", "fast food"],
  "burgers": ["burger", "burgers", "american", "fast food"],
  "chicken": ["chicken", "fried chicken", "grill"],
  "dosa": ["dosa", "south indian", "breakfast"],
  "idli": ["idli", "south indian", "breakfast"],
  "appam": ["appam", "kerala", "south indian"],
  "seafood": ["seafood", "fish", "prawns", "crab"],
  "fish": ["fish", "seafood", "prawns", "crab"],
  "shawarma roll": ["shawarma", "rolls", "arabian"],
};

function matchesRestaurantSearch(restaurant, rawQuery) {
  const query = String(rawQuery || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!query) return true;
  const fields = [
    restaurant.name, restaurant.cuisine, restaurant.cusine, restaurant.location,
    restaurant.type, restaurant.description, restaurant.category, restaurant.tags,
    restaurant.menu, restaurant.menuItems, restaurant.dishes, restaurant.foodItems,
    restaurant.items, restaurant.specialities, restaurant.specialties,
  ];
  const searchable = fields.flat(Infinity).filter(Boolean).join(" ").toLowerCase();
  if (searchable.includes(query)) return true;
  const tokens = query.split(" ").filter(Boolean);
  if (tokens.length > 1 && tokens.every((token) => searchable.includes(token))) return true;
  const aliases = SEARCH_SYNONYMS[query] || [];
  return aliases.some((alias) => searchable.includes(alias));
}

